public struct Vector3 {public float x,y,z;public Vector3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}public float sqrMagnitude=>x*x+y*y+z*z;public Vector3 normalized=>this/MathF.Sqrt(MathF.Max(sqrMagnitude,1e-20f));public void Normalize(){this=normalized;}public static Vector3 zero=>new();public static Vector3 one=>new(1,1,1);public static Vector3 up=>new(0,1,0);public static Vector3 right=>new(1,0,0);public static Vector3 left=>new(-1,0,0);public static Vector3 back=>new(0,0,-1);public static Vector3 operator -(Vector3 a,Vector3 b)=>new(a.x-b.x,a.y-b.y,a.z-b.z);public static Vector3 operator -(Vector3 a)=>new(-a.x,-a.y,-a.z);public static Vector3 operator +(Vector3 a,Vector3 b)=>new(a.x+b.x,a.y+b.y,a.z+b.z);public static Vector3 operator *(Vector3 a,float b)=>new(a.x*b,a.y*b,a.z*b);public static Vector3 operator /(Vector3 a,float b)=>new(a.x/b,a.y/b,a.z/b);public static float Dot(Vector3 a,Vector3 b)=>a.x*b.x+a.y*b.y+a.z*b.z;public static Vector3 Cross(Vector3 a,Vector3 b)=>new(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);public static Vector3 ProjectOnPlane(Vector3 a,Vector3 b)=>a-b*(Dot(a,b)/MathF.Max(b.sqrMagnitude,1e-20f));public static Vector3 Lerp(Vector3 a,Vector3 b,float t)=>a+(b-a)*t;}
